class Solution:
    def earliestSecondToMarkIndices(self, nums: List[int], changeIndices: List[int]) -> int:
        n = len(nums)
        m = len(changeIndices)

        # Check if all indices appear in changeIndices
        indices_set = set(changeIndices)
        if len(indices_set) < n:
            return -1

        def canMarkAll(seconds):
            # Convert to 0-indexed
            last_occurrence = {}
            for i in range(seconds):
                last_occurrence[changeIndices[i] - 1] = i

            # Check if all indices have occurred
            if len(last_occurrence) < n:
                return False

            # Create a copy of nums for simulation
            nums_copy = nums[:]
            marked = [False] * n

            # Process each second
            for s in range(seconds):
                idx = changeIndices[s] - 1

                # If this is the last occurrence of this index, we need to ensure it's 0
                if s == last_occurrence[idx]:
                    if nums_copy[idx] > 0:
                        return False
                    marked[idx] = True
                else:
                    # We can choose to decrement any index
                    # Priority: decrement indices that need to be 0 by their last occurrence
                    best_idx = -1
                    best_priority = -1

                    for i in range(n):
                        if nums_copy[i] > 0 and i in last_occurrence:
                            # Calculate how many operations we need vs time left
                            time_left = last_occurrence[i] - s
                            if time_left >= 0:
                                priority = nums_copy[i] - time_left
                                if priority > best_priority:
                                    best_priority = priority
                                    best_idx = i

                    if best_idx != -1:
                        nums_copy[best_idx] -= 1

            return all(marked)

        # Binary search for the earliest second
        left, right = 1, m
        result = -1

        while left <= right:
            mid = (left + right) // 2
            if canMarkAll(mid):
                result = mid
                right = mid - 1
            else:
                left = mid + 1

        return result
